import { deepStrictEqual, strictEqual } from 'node:assert';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ROOT, testServer, msgpack, localize } from './http-check.mjs';

// Select base desktop endpoints now generated by the SQLite read API.
function covered(url) {
  if (url.searchParams.has('template')) return false;
  return /^\/(cards(?:\/[^/]+)?|spaces(?:\/[^/]+)?|tags\/(manual|recent|suggest|detail)|changes|quota|quotas\/objects|objects\/[^/]+(?:\/(tags|content))?)$/.test(url.pathname);
}

// Blank CDN signatures, which live mymind re-issues on every recording and the replica cannot mint.
function unsign(value) {
  if (typeof value === 'string') return value.replace(/Expires=\d+(&(?:amp;)?)Signature=[^&"\s]+/g, 'Expires=$1Signature=');
  if (Array.isArray(value)) return value.map(unsign);
  if (value && typeof value === 'object' && !(value instanceof Date) && !ArrayBuffer.isView(value)) {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, unsign(item)]));
  }
  return value;
}

// Compare decoded values without printing private recording bodies on failures.
function equal(actual, expected, label) {
  try { deepStrictEqual(unsign(actual), unsign(expected)); }
  catch { throw new Error(`${label} differs`); }
}

const server = await testServer();
let passed = 0;
let failed = 0;
try {
  const index = JSON.parse(await readFile(join(ROOT, 'replay/index.json'), 'utf8'));
  for (const [key, entry] of Object.entries(index)) {
    if (!key.startsWith('GET https://access.mymind.com/')) continue;
    const url = new URL(key.slice(4));
    if (!covered(url)) continue;
    const endpoint = url.pathname + url.search;
    const label = `GET ${endpoint.replace(/[0-9A-Za-z]{22}/g, ':id')}`;
    try {
      const expected = await readFile(join(ROOT, 'replay/bodies', entry.file));
      const type = entry.headers['content-type'] ?? '';
      const { response, bytes } = await server.request(endpoint, { accept: type });
      strictEqual(response.status, entry.status, 'status');
      for (const name of ['content-type', 'x-object-quota', 'x-checkpoint', 'x-count', 'x-partial', 'access-control-expose-headers']) {
        if (entry.headers[name] !== undefined) strictEqual(response.headers.get(name), entry.headers[name], name);
      }
      if (type.includes('msgpack')) equal([...msgpack.decodeMulti(bytes)], localize([...msgpack.decodeMulti(expected)]), 'msgpack body');
      else if (type.includes('json')) equal(JSON.parse(bytes), localize(JSON.parse(expected)), 'JSON body');
      else equal(bytes, /text|javascript|svg|xml/.test(type) ? Buffer.from(localize(expected.toString())) : expected, 'body bytes');
      console.log(`PASS  ${label}`);
      passed++;
    } catch (error) {
      console.log(`FAIL  ${label}: ${error.message.split('\n')[0]}`);
      failed++;
    }
  }
  for (const [key, entry] of Object.entries(index)) {
    if (!/^GET https:\/\/access.mymind.com\/(?:cards\/[^/]+(?:\/detail|\/reader|\?template=PinnedCard)|queries\/[^/]+\/check)$/.test(key)) continue;
    const url = new URL(key.slice(4));
    try {
      const expected = await readFile(join(ROOT, 'replay/bodies', entry.file));
      const result = await server.request(url.pathname + url.search, { accept: entry.headers['content-type'] });
      strictEqual(result.response.status, entry.status);
      equal(result.bytes, Buffer.from(localize(expected.toString())), 'fallback bytes');
      console.log(`PASS  replay fallback ${url.pathname.replace(/[0-9A-Za-z]{22}/g, ':id')}${url.search}`);
      passed++;
    } catch (error) { console.log(`FAIL  replay fallback: ${error.message.split('\n')[0]}`); failed++; }
  }
  try {
    const entry = index['iphone|GET https://access.mymind.com/cards'] ?? index['GET https://access.mymind.com/cards'];
    const expected = localize([...msgpack.decodeMulti(await readFile(join(ROOT, 'replay/bodies', entry.file)))]);
    const result = await server.request('/cards', { accept: 'application/msgpack', headers: { 'user-agent': 'iPhone' } });
    equal(result.value, expected, 'phone body');
    console.log('PASS  phone /cards retains device replay'); passed++;
  } catch (error) { console.log(`FAIL  phone replay: ${error.message.split('\n')[0]}`); failed++; }
  try {
    const entry = index['iphone|DOC https://access.mymind.com/everything'] ?? index['DOC https://access.mymind.com/everything'];
    const expected = entry ? await readFile(join(ROOT, 'replay/bodies', entry.file)) : await readFile(join(ROOT, 'capture/shell.html'));
    const result = await server.request('/everything', { accept: 'text/html', headers: { 'user-agent': 'iPhone', 'sec-fetch-dest': 'document' } });
    equal(result.bytes, Buffer.from(localize(expected.toString())), 'phone shell bytes');
    console.log('PASS  phone shell retains device replay'); passed++;
  } catch (error) { console.log(`FAIL  phone shell replay: ${error.message.split('\n')[0]}`); failed++; }
  const legacy = await testServer({ noStore: true });
  try {
    const entry = index['GET https://access.mymind.com/cards'];
    const expected = localize([...msgpack.decodeMulti(await readFile(join(ROOT, 'replay/bodies', entry.file)))]);
    equal((await legacy.request('/cards', { accept: 'application/msgpack' })).value, expected, 'legacy grid');
    equal((await legacy.request('/objects', { method: 'POST', body: { content: 'ignored' } })).value, {}, 'legacy write acknowledgment');
    console.log('PASS  missing database retains replay and write acknowledgments'); passed++;
  } catch (error) { console.log(`FAIL  legacy replay: ${error.message.split('\n')[0]}`); failed++; }
  finally { await legacy.close(); }
  try {
    const entry = index['GET https://access.mymind.com/cards'];
    const cards = localize([...msgpack.decodeMulti(await readFile(join(ROOT, 'replay/bodies', entry.file)))]);
    const selected = [cards.at(-1), cards[0], cards[100]];
    const ids = selected.map(card => card.html.match(/data-id="([^"]+)"/)[1]);
    const result = await server.request('/cards/grid', { method: 'POST', body: ids, accept: 'application/msgpack' });
    strictEqual(result.response.status, 200);
    equal(result.value, selected, 'hydrated cards');
    console.log('PASS  POST /cards/grid (requested order)');
    passed++;
  } catch (error) { console.log(`FAIL  POST /cards/grid: ${error.message.split('\n')[0]}`); failed++; }
} finally {
  await server.close();
}
console.log(`\n${passed}/${passed + failed} read checks passed${process.argv.includes('--in-process') ? ' (in-process transport)' : ''}`);
process.exitCode = failed ? 1 : 0;
